#!/usr/bin/env bash
#
# Build a plugin-bundled OBS AppImage.
#
# Strategy: extract the pinned official OBS Studio AppImage, drop the plugin
# module + data into its AppDir, re-package with appimagetool. The result is
# a self-contained AppImage whose name carries both the OBS and plugin
# versions for traceability.
#
# Inputs (environment):
#   OBS_APPIMAGE      - path to the verified official OBS AppImage (required)
#   INSTALL_DIR       - plugin install tree from cmake --install (required)
#   META_FILE         - plugin-meta.txt generated by CMake (required)
#   OUTPUT_DIR        - output directory (default: dist)
#   APPIMAGETOOL      - path to appimagetool (default: from PATH)

set -euo pipefail

: "${OBS_APPIMAGE:?OBS_APPIMAGE is required}"
: "${INSTALL_DIR:?INSTALL_DIR is required}"
: "${META_FILE:?META_FILE is required}"

OUTPUT_DIR="${OUTPUT_DIR:-dist}"
APPIMAGETOOL="${APPIMAGETOOL:-appimagetool}"

# shellcheck disable=SC1090
source "${META_FILE}"

WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT
APPDIR="${WORK}/AppDir"

# 1. Extract the base OBS AppImage without FUSE (works inside containers).
chmod +x "${OBS_APPIMAGE}"
"${OBS_APPIMAGE}" --appimage-extract >/dev/null
mv squashfs-root "${APPDIR}"

# 2. Locate where OBS keeps plugins inside the AppDir.
PLUGIN_DEST="$(find "${APPDIR}" -type d -name obs-plugins -print -quit)"
if [ -z "${PLUGIN_DEST}" ]; then
	echo "error: obs-plugins directory not found in ${APPDIR}" >&2
	exit 1
fi

# 3. Copy the plugin module and its data files into the AppDir.
cp -a "${INSTALL_DIR}/." "${APPDIR}/"

# 4. Stamp plugin metadata into the desktop file for version traceability.
DESKTOP_FILE="$(find "${APPDIR}" -name '*.desktop' -print -quit)"
if [ -n "${DESKTOP_FILE}" ]; then
	echo "X-Plugin-Name=${PLUGIN_NAME}" >> "${DESKTOP_FILE}"
	echo "X-Plugin-Version=${PLUGIN_VERSION}" >> "${DESKTOP_FILE}"
fi

# 5. Repack. ARCH makes the name reproducible across host configurations.
ARCH="$(uname -m)"
OUT_NAME="OBS-Studio-with-${PLUGIN_TARGET}-${PLUGIN_VERSION}-${ARCH}.AppImage"
mkdir -p "${OUTPUT_DIR}"
ARCH="${ARCH}" "${APPIMAGETOOL}" --no-appstream "${APPDIR}" "${OUTPUT_DIR}/${OUT_NAME}"
chmod +x "${OUTPUT_DIR}/${OUT_NAME}"

echo "Created ${OUTPUT_DIR}/${OUT_NAME}"
